function validate([arr, brr, k]) {
  if (arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  if (brr.length !== arr.length) return 'arr and brr must have the same length.';
  if (arr.some(v => v < -100000 || v > 100000) || brr.some(v => v < -100000 || v > 100000)) return 'Each value is between -10^5 and 10^5.';
  if (k < 0 || k > 20000000000) return 'k is between 0 and 2 * 10^10.';
  return null;
}

