function minCost(arr, brr, k) {
  // Either keep the order for free, or pay k once and try every order of arr's elements.
  const n = arr.length;
  let keep = 0;
  for (let i = 0; i < n; i++) keep += Math.abs(arr[i] - brr[i]);
  let bestOrder = Infinity;
  const used = new Array(n).fill(false);
  const place = (i, cost) => {
    if (i === n) { bestOrder = Math.min(bestOrder, cost); return; }
    for (let j = 0; j < n; j++) {
      if (used[j]) continue;
      used[j] = true;
      place(i + 1, cost + Math.abs(arr[j] - brr[i]));
      used[j] = false;
    }
  };
  place(0, 0);
  return Math.min(keep, k + bestOrder);
}

