function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = pick(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const large = size === 'large';
  const n = large ? 2000 : 1 + pick(7);
  const span = large ? 100000 : [3, 10, 100000][pick(3)];
  const value = () => pick(2 * span + 1) - span;
  const clamp = v => Math.max(-100000, Math.min(100000, v));
  const arr = Array.from({ length: n }, value);
  // brr is independent, a shuffled copy of arr, or arr itself, each with a little noise or none.
  const shape = pick(3), noise = [0, 1, 5][pick(3)];
  const base = shape === 0 ? Array.from({ length: n }, value) : shape === 1 ? shuffle([...arr]) : [...arr];
  const brr = base.map(v => clamp(v + pick(2 * noise + 1) - noise));
  // k is zero, the largest allowed, or near the cost of fixing the order directly, so both plans can win.
  let direct = 0;
  for (let i = 0; i < n; i++) direct += Math.abs(arr[i] - brr[i]);
  const choice = pick(4);
  const k = choice === 0 ? 0 : choice === 1 ? 20000000000 : pick(2 * direct + 2);
  return [arr, brr, k];
}
